-- 137: equilíbrio de trilhas, lote 2
-- 100 questões novas (50 de Igualdade Racial e de Gênero e 50 de Pessoas com Deficiência, 10 por nível), ids 11687 a 11786.
-- Revisão de 5 questões de IA que citavam a Resolução CNJ 332/2020, revogada pela Resolução CNJ 615/2025 (ids 3166, 3167, 3168, 3274 e 3275).
-- Pode rodar mais de uma vez: usa upsert por id.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[
{"id": 3166, "materia": "ia", "nivel": 2, "enunciado": "A Resolução CNJ 615/2025, que substituiu a Resolução 332/2020, trata:", "opcoes": ["Do desenvolvimento, da governança, da auditoria e do uso de IA no Poder Judiciário", "Da acessibilidade de pessoas com deficiência nos sistemas eletrônicos dos tribunais", "Da política ambiental e de sustentabilidade do Poder Judiciário", "Da gestão e do pagamento de precatórios pela União e pelos estados"], "explicacao": "A Res. CNJ 615, de 11/3/2025, revogou a Res. 332/2020 e criou, entre outros pontos, a classificação de soluções de IA por grau de risco."},
{"id": 3167, "materia": "ia", "nivel": 3, "enunciado": "Pela Resolução CNJ 615/2025, o Sinapses é:", "opcoes": ["A solução do CNJ para armazenar, testar, treinar, distribuir e auditar modelos de IA", "O sistema de peticionamento eletrônico do STF usado por advogados, defensores e procuradores", "A rede social interna dos servidores do Poder Judiciário", "O banco nacional de mandados de prisão mantido pelo CNJ"], "explicacao": "Art. 4º, III, da Res. 615/2025. O art. 24 exige o cadastro no Sinapses das soluções de IA em uso ou em desenvolvimento."},
{"id": 3168, "materia": "ia", "nivel": 3, "enunciado": "Pela Resolução CNJ 615/2025, é vedado aos tribunais usar solução de IA que:", "opcoes": ["Preveja crimes ou reincidência a partir de traços de personalidade ou comportamento", "Resuma documentos e faça transcrições de audiências, sempre com supervisão humana", "Classifique processos por assunto para organizar a distribuição", "Ajude na pesquisa de jurisprudência, com conferência do servidor"], "explicacao": "Art. 10, II. Resumir, transcrever e classificar são tarefas de baixo risco, permitidas com supervisão humana."},
{"id": 3274, "materia": "ia", "nivel": 4, "enunciado": "Pela Resolução CNJ 615/2025, os usuários externos devem ser informados, em linguagem clara e simples, sobre o uso de IA, com destaque para:", "opcoes": ["O caráter consultivo e não vinculante da proposta da IA, sujeita à decisão de autoridade competente", "A impossibilidade de recorrer de decisões que tenham sido elaboradas com o apoio de ferramentas de IA", "A obrigatoriedade de o juiz citar no texto da sentença o nome da ferramenta usada", "A dispensa de revisão humana nos processos de menor complexidade"], "explicacao": "Art. 33, caput e § 1º. Pelo § 3º, mencionar o uso de IA no texto da decisão é facultativo para o signatário."},
{"id": 3275, "materia": "ia", "nivel": 4, "enunciado": "Pela Resolução CNJ 615/2025, quanto ao uso de IA generativa como apoio às decisões judiciais:", "opcoes": ["É vedado o uso autônomo, e o magistrado permanece integralmente responsável pela decisão", "A IA pode assinar decisões simples, se o juiz aprovar o modelo antes", "O magistrado deixa de responder pelos erros da ferramenta, que passam a ser do fornecedor contratado", "O uso é livre, desde que a parte contrária não se oponha"], "explicacao": "Art. 19, § 3º, II. O art. 34 exige supervisão humana e permite ao magistrado modificar qualquer produto gerado pela IA."},
{"id": 11687, "materia": "igual", "nivel": 0, "enunciado": "O Dia Internacional da Mulher é comemorado em:", "opcoes": ["8 de março", "20 de novembro", "1º de maio", "25 de dezembro"], "explicacao": "O 8 de março lembra a luta das mulheres por direitos e igualdade. O 20 de novembro é o Dia Nacional de Zumbi e da Consciência Negra."},
{"id": 11688, "materia": "igual", "nivel": 0, "enunciado": "Pela Lei 14.541/2023, as Delegacias Especializadas de Atendimento à Mulher (Deam) devem funcionar:", "opcoes": ["24 horas por dia, inclusive em feriados e fins de semana", "Apenas em horário comercial, de segunda a sexta", "Somente à noite, quando há mais casos", "Apenas nos dias úteis, com plantão aos domingos"], "explicacao": "A Lei 14.541/2023 garante o funcionamento ininterrupto das Deam, com atendimento preferencialmente por policiais mulheres, em sala reservada."},
{"id": 11689, "materia": "igual", "nivel": 0, "enunciado": "Pagar salário menor a uma mulher que exerce a mesma função de um homem, na mesma empresa, é:", "opcoes": ["Discriminação proibida pela lei", "Permitido, se a empresa quiser", "Obrigatório em empresas pequenas", "Permitido no primeiro ano de trabalho"], "explicacao": "A Constituição (art. 7º, XXX) e a Lei 14.611/2023 proíbem diferença salarial por motivo de sexo para trabalho de igual valor ou na mesma função."},
{"id": 11690, "materia": "igual", "nivel": 0, "enunciado": "Zumbi, homenageado no Dia da Consciência Negra, foi líder do:", "opcoes": ["Quilombo dos Palmares", "Movimento abolicionista inglês", "Império do Brasil", "Exército da Guerra do Paraguai"], "explicacao": "Zumbi liderou o Quilombo dos Palmares, na Serra da Barriga (atual Alagoas), símbolo da resistência à escravidão. Foi morto em 20 de novembro de 1695."},
{"id": 11691, "materia": "igual", "nivel": 0, "enunciado": "Pichar e destruir um terreiro de candomblé por ódio à religião é um ato de:", "opcoes": ["Intolerância religiosa, que é crime", "Liberdade de expressão, permitida pela Constituição", "Simples dano ao patrimônio, sem importância penal", "Protesto político autorizado por lei"], "explicacao": "A Lei 7.716/1989 pune a discriminação por religião, e o Estatuto da Igualdade Racial protege as religiões de matriz africana."},
{"id": 11692, "materia": "igual", "nivel": 0, "enunciado": "A escravidão foi abolida oficialmente no Brasil em 1888, pela:", "opcoes": ["Lei Áurea", "Lei do Ventre Livre", "Lei dos Sexagenários", "Constituição de 1824"], "explicacao": "A Lei Áurea (Lei 3.353/1888) extinguiu a escravidão. A Lei do Ventre Livre é de 1871, e a dos Sexagenários, de 1885."},
{"id": 11693, "materia": "igual", "nivel": 0, "enunciado": "A medida protetiva de urgência da Lei Maria da Penha serve para:", "opcoes": ["Proteger a mulher, afastando o agressor", "Punir a mulher que fez a denúncia contra o companheiro", "Obrigar o casal a continuar morando na mesma casa", "Proibir a mulher de sair de casa enquanto durar o processo"], "explicacao": "Medidas protetivas, como afastamento do lar e proibição de aproximação, protegem a mulher enquanto houver risco."},
{"id": 11694, "materia": "igual", "nivel": 0, "enunciado": "Constranger alguém, no trabalho, para obter vantagem sexual, valendo-se da condição de chefe, é crime de:", "opcoes": ["Assédio sexual", "Furto", "Estelionato", "Desacato"], "explicacao": "Art. 216-A do Código Penal: assédio sexual é constranger alguém com o intuito de obter vantagem ou favorecimento sexual, prevalecendo-se da condição de superior hierárquico."},
{"id": 11695, "materia": "igual", "nivel": 0, "enunciado": "Desde a Lei 14.402/2022, o 19 de abril passou a se chamar:", "opcoes": ["Dia dos Povos Indígenas", "Dia do Índio", "Dia da Abolição", "Dia da Diversidade"], "explicacao": "A Lei 14.402/2022 trocou o nome “Dia do Índio” por “Dia dos Povos Indígenas”, valorizando a diversidade dos povos originários."},
{"id": 11696, "materia": "igual", "nivel": 0, "enunciado": "Um vizinho que ouve uma mulher sendo agredida em casa pode:", "opcoes": ["Denunciar pelo 190 ou pelo Ligue 180", "Não fazer nada, porque só a própria vítima pode denunciar", "Denunciar apenas se tiver parentesco com a vítima", "Esperar a vítima autorizar a denúncia por escrito"], "explicacao": "Qualquer pessoa pode e deve denunciar violência contra a mulher. Em emergência, o 190; para orientação e denúncia, o Ligue 180."},
{"id": 11697, "materia": "igual", "nivel": 1, "enunciado": "Pela Lei 7.716/1989, são punidos os crimes resultantes de discriminação ou preconceito de:", "opcoes": ["Raça, cor, etnia, religião ou procedência nacional", "Apenas raça e cor, sem nenhuma outra hipótese prevista", "Raça e classe social, somente, por força da Constituição", "Cor e idade, somente, desde a reforma da lei em 2023"], "explicacao": "Art. 1º da Lei 7.716/1989. Por decisão do STF (ADO 26), também se enquadram na lei a homofobia e a transfobia."},
{"id": 11698, "materia": "igual", "nivel": 1, "enunciado": "A Lei 14.245/2021, conhecida como Lei Mariana Ferrer, protege as vítimas, especialmente de crimes sexuais, contra:", "opcoes": ["Ofensas à sua dignidade em audiências e julgamentos", "A divulgação pública do resultado final do processo", "A presença do advogado do réu durante as audiências", "O pagamento das custas processuais ao final da ação"], "explicacao": "A Lei 14.245/2021 proíbe manifestações sobre fatos alheios ao processo e o uso de linguagem ou material que ofendam a dignidade da vítima e das testemunhas."},
{"id": 11699, "materia": "igual", "nivel": 1, "enunciado": "Praticar ato libidinoso contra alguém, sem sua anuência, para satisfazer o próprio desejo, como no assédio em transporte público, é crime de:", "opcoes": ["Importunação sexual", "Ato obsceno", "Constrangimento ilegal", "Injúria"], "explicacao": "A importunação sexual (art. 215-A do CP) foi criada pela Lei 13.718/2018, com pena de reclusão de 1 a 5 anos, se o ato não constituir crime mais grave."},
{"id": 11700, "materia": "igual", "nivel": 1, "enunciado": "A Convenção 169 da Organização Internacional do Trabalho (OIT) assegura aos povos indígenas e tribais o direito de:", "opcoes": ["Serem consultados de forma prévia, livre e informada", "Escolher a religião oficial do Estado em cada região onde vivem", "Não pagar nenhum tributo em todo o território nacional, em qualquer situação", "Vetar qualquer lei aprovada pelo Congresso Nacional"], "explicacao": "A consulta prévia, livre e informada é um dos pilares da Convenção 169, ratificada pelo Brasil."},
{"id": 11701, "materia": "igual", "nivel": 1, "enunciado": "A Lei 13.642/2018, conhecida como Lei Lola, atribuiu à Polícia Federal a investigação de crimes praticados pela internet que:", "opcoes": ["Difundam conteúdo misógino, de ódio às mulheres", "Envolvam qualquer ofensa pessoal trocada entre particulares", "Tratem da pirataria de filmes, músicas e programas de computador", "Tenham prejuízo superior a 100 salários mínimos para a vítima"], "explicacao": "A Lei 13.642/2018 alterou a Lei 10.446/2002 para incluir na atribuição da PF os crimes pela internet que difundam conteúdo misógino."},
{"id": 11702, "materia": "igual", "nivel": 1, "enunciado": "Após a Lei 14.443/2022, a esterilização voluntária (laqueadura ou vasectomia):", "opcoes": ["Não depende mais do consentimento do cônjuge", "Passou a exigir autorização judicial", "Ficou proibida para mulheres casadas", "Depende da autorização dos pais até os 30 anos"], "explicacao": "A Lei 14.443/2022 retirou a exigência de consentimento do cônjuge e reduziu a idade mínima para 21 anos (ou dois filhos vivos)."},
{"id": 11703, "materia": "igual", "nivel": 1, "enunciado": "Segundo o STF (ADI 4.275), pessoas transgênero podem alterar nome e gênero no registro civil:", "opcoes": ["Sem cirurgia e sem autorização judicial", "Apenas depois da cirurgia de redesignação sexual", "Somente com laudo psiquiátrico e ordem do juiz da comarca", "Apenas depois dos 30 anos de idade e com testemunhas"], "explicacao": "O STF reconheceu o direito à alteração diretamente no cartório, por autodeclaração, sem exigir cirurgia, laudos ou decisão judicial."},
{"id": 11704, "materia": "igual", "nivel": 1, "enunciado": "O feminicídio, pela Lei 8.072/1990, é crime:", "opcoes": ["Hediondo", "De menor potencial ofensivo", "Culposo, em regra", "Afiançável pelo delegado"], "explicacao": "O feminicídio está no rol dos crimes hediondos. Desde a Lei 14.994/2024, é crime autônomo (art. 121-A do CP)."},
{"id": 11705, "materia": "igual", "nivel": 1, "enunciado": "Pela Lei Maria da Penha, empurrar, bater ou machucar a mulher configura violência:", "opcoes": ["Física", "Moral", "Patrimonial", "Psicológica"], "explicacao": "Violência física é qualquer conduta que ofenda a integridade ou a saúde corporal da mulher (art. 7º, I, da Lei 11.340/2006)."},
{"id": 11706, "materia": "igual", "nivel": 1, "enunciado": "Pela Constituição, a lei punirá:", "opcoes": ["Qualquer discriminação atentatória dos direitos fundamentais", "Apenas a discriminação praticada por agentes públicos no exercício da função", "Somente a discriminação que causar dano financeiro comprovado à vítima", "Apenas a discriminação feita por escrito ou em meios de comunicação"], "explicacao": "Art. 5º, XLI, da CF. O inciso XLII trata do racismo como crime inafiançável e imprescritível."},
{"id": 11707, "materia": "igual", "nivel": 2, "enunciado": "Pela Súmula 600 do STJ, para a configuração da violência doméstica e familiar prevista na Lei Maria da Penha:", "opcoes": ["Não se exige a coabitação entre autor e vítima", "É indispensável que agressor e vítima morem juntos", "Exige-se casamento civil registrado", "É preciso que o casal tenha filhos em comum"], "explicacao": "Súmula 600 do STJ: não se exige coabitação. Basta relação íntima de afeto, presente ou passada, ou vínculo familiar ou doméstico."},
{"id": 11708, "materia": "igual", "nivel": 2, "enunciado": "Pela Súmula 536 do STJ, nos delitos sujeitos ao rito da Lei Maria da Penha:", "opcoes": ["Não se aplicam a suspensão condicional do processo e a transação penal", "Aplica-se sempre a transação penal, se o réu for primário e de bons antecedentes", "A suspensão condicional do processo é obrigatória quando a pena mínima for de 1 ano", "O juiz pode substituir a pena por cesta básica, desde que a vítima concorde"], "explicacao": "Súmula 536 do STJ, em linha com o art. 41 da Lei 11.340/2006, que afasta a Lei 9.099/1995."},
{"id": 11709, "materia": "igual", "nivel": 2, "enunciado": "Após a Lei 14.550/2023, as medidas protetivas de urgência da Lei Maria da Penha:", "opcoes": ["Podem ser concedidas independentemente de boletim de ocorrência, inquérito ou ação penal", "Só podem ser concedidas depois da denúncia do Ministério Público", "Dependem de prova testemunhal do fato", "Exigem que a vítima tenha lesões comprovadas por perícia"], "explicacao": "O art. 19, §§ 4º a 6º, da Lei 11.340/2006 (Lei 14.550/2023) dispensa tipificação penal, registro de BO, inquérito ou ação, e as medidas vigoram enquanto persistir o risco."},
{"id": 11710, "materia": "igual", "nivel": 2, "enunciado": "A Lei 14.723/2023, que atualizou a Lei de Cotas nas universidades federais (Lei 12.711/2012):", "opcoes": ["Incluiu os quilombolas e prevê avaliação a cada 10 anos", "Acabou com as cotas raciais em todas as universidades federais do país", "Reduziu a reserva de vagas de 50% para apenas 10% das vagas oferecidas", "Restringiu as cotas aos cursos de licenciatura e de formação de professores"], "explicacao": "A Lei 14.723/2023 incluiu os quilombolas, estabeleceu que os cotistas concorram primeiro na ampla concorrência e fixou avaliação periódica a cada 10 anos."},
{"id": 11711, "materia": "igual", "nivel": 2, "enunciado": "A diferença entre injúria racial e racismo, na classificação tradicional, é que:", "opcoes": ["A injúria ofende pessoa determinada; o racismo atinge a coletividade ou impede direitos", "A injúria é sempre praticada por escrito, e o racismo, sempre de forma verbal e em público", "O racismo é crime, e a injúria racial é apenas infração administrativa punida com multa", "Não há qualquer diferença entre os dois na lei nem na interpretação dos tribunais"], "explicacao": "Hoje ambos estão na Lei 7.716/1989 (a injúria racial no art. 2º-A, desde a Lei 14.532/2023), mas a injúria continua voltada à ofensa de pessoa determinada."},
{"id": 11712, "materia": "igual", "nivel": 2, "enunciado": "A Lei 14.321/2022 criou o crime de violência institucional, que consiste em submeter a vítima ou testemunha de crime violento a:", "opcoes": ["Procedimentos desnecessários que a façam reviver a violência", "Prisão preventiva decretada sem ordem judicial escrita e fundamentada", "Pagamento antecipado de custas e honorários do processo criminal", "Depoimento por videoconferência, sem a presença física do juiz"], "explicacao": "Art. 15-A da Lei 13.869/2019 (Abuso de Autoridade), incluído pela Lei 14.321/2022, com pena de detenção de 3 meses a 1 ano e multa."},
{"id": 11713, "materia": "igual", "nivel": 2, "enunciado": "Pela Constituição, é proibida a diferença de salários, de exercício de funções e de critério de admissão por motivo de:", "opcoes": ["Sexo, idade, cor ou estado civil", "Escolaridade ou experiência profissional", "Tempo de serviço na empresa", "Produtividade comprovada"], "explicacao": "Art. 7º, XXX, da CF. Diferenças baseadas em critérios objetivos, como experiência e produtividade, não são discriminação."},
{"id": 11714, "materia": "igual", "nivel": 2, "enunciado": "O termo “racismo estrutural” designa:", "opcoes": ["O racismo inserido no funcionamento normal das instituições", "Apenas os atos de ofensa racial praticados de forma isolada por indivíduos", "O racismo previsto exclusivamente no texto da Constituição Federal", "A discriminação praticada contra pessoas com deficiência no trabalho"], "explicacao": "A ideia é que desigualdades raciais se reproduzem pelas regras, práticas e estruturas sociais, o que justifica políticas como as ações afirmativas."},
{"id": 11715, "materia": "igual", "nivel": 2, "enunciado": "Pela Lei Maria da Penha, a violência doméstica e familiar contra a mulher pode ocorrer no âmbito:", "opcoes": ["Da unidade doméstica, da família ou de relação íntima de afeto", "Apenas do casamento civil registrado em cartório", "Apenas da residência em que o casal mora junto", "Somente entre pessoas de sexos diferentes, casadas ou não"], "explicacao": "Art. 5º da Lei 11.340/2006. O parágrafo único esclarece que as relações independem de orientação sexual."},
{"id": 11716, "materia": "igual", "nivel": 2, "enunciado": "O Brasil incorporou com status de emenda constitucional, por ter sido aprovada pelo rito do art. 5º, § 3º, da CF, a:", "opcoes": ["Convenção Interamericana contra o Racismo", "Convenção de Belém do Pará, sobre violência contra a mulher", "Declaração Universal dos Direitos Humanos, de 1948", "Convenção 169 da OIT, sobre povos indígenas e tribais"], "explicacao": "A Convenção Interamericana contra o Racismo foi aprovada com quórum de emenda e promulgada pelo Decreto 10.932/2022. A Convenção de Belém do Pará e a Convenção 169 têm status supralegal."},
{"id": 11717, "materia": "igual", "nivel": 3, "enunciado": "Pela Súmula 588 do STJ, a prática de crime ou contravenção contra a mulher com violência ou grave ameaça no ambiente doméstico:", "opcoes": ["Impede substituir a prisão por pena restritiva de direitos", "Permite a substituição da pena por cesta básica ou prestação pecuniária", "Autoriza a transação penal se o réu for primário e de bons antecedentes", "Impede apenas a suspensão condicional da pena, mas não a substituição"], "explicacao": "Súmula 588 do STJ, combinada com o art. 44, I, do CP, que veda a substituição quando há violência ou grave ameaça."},
{"id": 11718, "materia": "igual", "nivel": 3, "enunciado": "No julgamento da ADPF 779, o STF decidiu que a tese da legítima defesa da honra:", "opcoes": ["É inconstitucional e não pode ser usada nem no Júri", "Pode ser usada no Júri, em respeito à plenitude de defesa garantida pela Constituição", "Só é proibida nos crimes cometidos contra crianças e adolescentes", "Pode ser usada se ficar provado que a vítima traiu o réu"], "explicacao": "O STF considerou a tese contrária à dignidade da pessoa humana e à igualdade de gênero. Seu uso pode levar à nulidade do julgamento."},
{"id": 11719, "materia": "igual", "nivel": 3, "enunciado": "Em 2022, o STJ decidiu (REsp 1.977.124) que a Lei Maria da Penha:", "opcoes": ["Aplica-se à violência doméstica contra mulheres transgênero", "Não se aplica a mulheres trans, por exigir sexo biológico feminino", "Só se aplica a mulheres casadas no civil", "Vale apenas para vítimas com mais de 18 anos"], "explicacao": "Para o STJ, a lei protege a mulher em razão do gênero, alcançando mulheres trans em relações domésticas, familiares ou íntimas."},
{"id": 11720, "materia": "igual", "nivel": 3, "enunciado": "Nos crimes da Lei 7.716/1989 cometidos por meios de comunicação ou redes sociais, o juiz pode determinar, ainda no inquérito, sob pena de desobediência:", "opcoes": ["O recolhimento de exemplares e a interdição das páginas", "A prisão preventiva automática do autor, sem audiência de custódia", "O fechamento definitivo da rede social em todo o território brasileiro", "A cassação dos direitos políticos do autor por oito anos"], "explicacao": "Art. 20, § 3º, da Lei 7.716/1989: recolhimento ou busca e apreensão de exemplares, cessação das transmissões e interdição das mensagens ou páginas na internet."},
{"id": 11721, "materia": "igual", "nivel": 3, "enunciado": "Ao julgar a ADI 3.239, o STF validou, para identificar as comunidades quilombolas, o critério de:", "opcoes": ["Autoatribuição, previsto no Decreto 4.887/2003", "Laudo genético obrigatório feito pela Polícia Federal", "Comprovação documental de ocupação da terra desde 1888", "Decisão exclusiva do Ministério Público Federal, sem recurso"], "explicacao": "O STF considerou constitucional o Decreto 4.887/2003, que regula a titulação das terras quilombolas e adota a autoatribuição como critério de identificação."},
{"id": 11722, "materia": "igual", "nivel": 3, "enunciado": "Pela Lei 9.504/1997, cada partido ou federação deve preencher, nas candidaturas proporcionais, o mínimo de:", "opcoes": ["30% e o máximo de 70% para cada sexo", "50% de candidaturas femininas em todas as eleições, inclusive majoritárias", "20% de candidaturas femininas, somente nas eleições municipais", "10% de candidaturas de cada sexo, por exigência da Constituição"], "explicacao": "Art. 10, § 3º, da Lei 9.504/1997. A cota é de candidaturas de cada sexo, e na prática protege as mulheres, sub-representadas na política."},
{"id": 11723, "materia": "igual", "nivel": 3, "enunciado": "Pela Súmula 73 do TSE, comprovada a fraude à cota de gênero com candidaturas femininas fictícias, uma das consequências é:", "opcoes": ["A cassação de toda a chapa vinculada ao DRAP", "A cassação apenas da candidata fictícia, mantidos os demais eleitos", "Uma multa ao partido, sem nenhum efeito sobre os candidatos eleitos", "A suspensão da eleição em todo o estado até nova votação"], "explicacao": "A Súmula 73 do TSE lista indícios de fraude (votação zerada ou ínfima, prestação de contas padronizada, ausência de campanha) e prevê a cassação de toda a chapa, além da inelegibilidade de quem praticou ou anuiu à fraude."},
{"id": 11724, "materia": "igual", "nivel": 3, "enunciado": "Pela Lei Maria da Penha (art. 14-A), a ofendida pode propor ação de divórcio no Juizado de Violência Doméstica e Familiar contra a Mulher:", "opcoes": ["Excluída a pretensão relacionada à partilha de bens", "Incluindo, obrigatoriamente, a partilha de todos os bens do casal", "Somente se já houver condenação criminal definitiva do agressor", "Apenas se o casal não tiver filhos menores de idade em comum"], "explicacao": "O art. 14-A, incluído pela Lei 13.894/2019, dá à ofendida a opção de propor o divórcio no juizado especializado, sem a partilha de bens, que segue em outro juízo."},
{"id": 11725, "materia": "igual", "nivel": 3, "enunciado": "Pela Lei Maria da Penha, a mulher em situação de violência doméstica tem direito a atendimento policial e pericial especializado, prestado preferencialmente por:", "opcoes": ["Servidoras mulheres previamente capacitadas", "Policiais militares em viatura, no local do fato", "Qualquer servidor que estiver disponível no plantão", "Advogados indicados pela OAB para acompanhar o caso"], "explicacao": "Art. 10-A da Lei 11.340/2006, incluído pela Lei 13.505/2017, que também veda a revitimização e o contato com o agressor."},
{"id": 11726, "materia": "igual", "nivel": 3, "enunciado": "Para proteger a integridade física e psicológica da mulher em situação de violência doméstica, o juiz pode assegurar a manutenção do vínculo trabalhista, quando necessário o afastamento do local de trabalho, por até:", "opcoes": ["6 meses", "1 mês", "1 ano", "2 anos"], "explicacao": "Art. 9º, § 2º, II, da Lei 11.340/2006. A servidora pública tem acesso prioritário à remoção (inciso I)."},
{"id": 11727, "materia": "igual", "nivel": 4, "enunciado": "Pela Resolução CNJ 492/2023, o Protocolo para Julgamento com Perspectiva de Gênero:", "opcoes": ["Passou a ser obrigatório no Poder Judiciário", "É apenas uma recomendação, sem nenhum efeito prático nos julgamentos", "Vale somente para a Justiça do Trabalho e para a Justiça Eleitoral", "Substituiu a Lei Maria da Penha nos casos de violência doméstica"], "explicacao": "A Resolução CNJ 492/2023 tornou obrigatórias as diretrizes do Protocolo e a capacitação de magistrados em direitos humanos, gênero, raça e etnia."},
{"id": 11728, "materia": "igual", "nivel": 4, "enunciado": "A Lei 14.245/2021 também alterou o Código Penal para aumentar a pena do crime de coação no curso do processo quando:", "opcoes": ["O processo envolver crime contra a dignidade sexual", "A vítima da coação for servidora pública federal ou estadual", "A coação for praticada por escrito ou por meio eletrônico", "O processo tramitar em segredo de justiça por ordem do juiz"], "explicacao": "Art. 344, parágrafo único, do CP: a pena aumenta de 1/3 até a metade se o processo envolver crime contra a dignidade sexual."},
{"id": 11729, "materia": "igual", "nivel": 4, "enunciado": "Pela Lei 7.716/1989 (art. 20-C, incluído pela Lei 14.532/2023), na interpretação da lei, o juiz deve considerar discriminatória qualquer atitude ou tratamento que:", "opcoes": ["Cause constrangimento ou humilhação a grupo minoritário e não se dispensaria a outros grupos", "Seja praticado apenas por agente público no exercício da função, em qualquer esfera de governo", "Resulte em lesão corporal comprovada por perícia oficial, ainda que de natureza leve", "Ocorra exclusivamente em meios de comunicação social, redes sociais ou publicações"], "explicacao": "O art. 20-C orienta a interpretação pelo efeito discriminatório da conduta, considerando cor, etnia, religião ou procedência."},
{"id": 11730, "materia": "igual", "nivel": 4, "enunciado": "Na Lei 15.142/2025 (cotas em concursos federais), a autodeclaração do candidato:", "opcoes": ["Pode passar por confirmação complementar, como a heteroidentificação", "É sempre definitiva e não admite qualquer tipo de verificação posterior", "Depende de exame genético feito por laboratório credenciado pelo órgão", "Só vale se for confirmada pela cor declarada na certidão de nascimento"], "explicacao": "A Lei 15.142/2025 prevê procedimentos de confirmação complementares à autodeclaração, com garantia de recurso, para evitar fraudes."},
{"id": 11731, "materia": "igual", "nivel": 4, "enunciado": "Pela Convenção de Belém do Pará, a violência contra a mulher abrange, além da ocorrida na família e na comunidade, a violência:", "opcoes": ["Perpetrada ou tolerada pelo Estado ou seus agentes", "Praticada apenas por desconhecidos em locais públicos, como ruas e praças", "Que deixe lesões graves comprovadas por exame de corpo de delito", "Ocorrida exclusivamente no ambiente de trabalho, por superiores hierárquicos"], "explicacao": "Art. 2º, c, da Convenção (Decreto 1.973/1996). O conceito inclui violência física, sexual e psicológica."},
{"id": 11732, "materia": "igual", "nivel": 4, "enunciado": "Pela CLT (art. 461, § 6º, incluído pela Lei 14.611/2023), comprovada a discriminação salarial por motivo de sexo, raça, etnia, origem ou idade, a multa devida ao empregado corresponde a:", "opcoes": ["10 vezes o novo salário devido, em dobro na reincidência", "1 salário mínimo, em qualquer caso, independentemente do porte da empresa", "50% do salário do mês da condenação, pago em parcela única", "Apenas ao valor da diferença salarial, sem qualquer multa adicional"], "explicacao": "Além das diferenças salariais, cabe a multa de 10 vezes o novo salário devido, dobrada na reincidência, sem prejuízo de indenização por danos morais."},
{"id": 11733, "materia": "igual", "nivel": 4, "enunciado": "O STF, no julgamento da ADC 41, declarou constitucional:", "opcoes": ["A reserva de 20% das vagas para negros em concursos federais (Lei 12.990/2014)", "A proibição de qualquer cota racial em concursos públicos, por violar a isonomia", "A reserva de vagas apenas em universidades estaduais, e não nos concursos", "A exigência de exame genético para comprovar a condição de cotista"], "explicacao": "Na ADC 41 (2017), o STF validou a Lei 12.990/2014 e admitiu mecanismos de heteroidentificação, respeitada a dignidade e garantidos o contraditório e a ampla defesa. A lei foi depois substituída pela Lei 15.142/2025."},
{"id": 11734, "materia": "igual", "nivel": 4, "enunciado": "Na ADI 4.424, o STF decidiu que, nos crimes de lesão corporal praticados contra a mulher no ambiente doméstico, a ação penal é:", "opcoes": ["Pública incondicionada, qualquer que seja a lesão", "Pública condicionada à representação, quando a lesão for leve ou culposa", "Privada, dependendo de queixa-crime da vítima no prazo de 6 meses", "Pública condicionada, mas extinta se o casal se reconciliar antes da sentença"], "explicacao": "O STF afastou a exigência de representação em qualquer lesão corporal no contexto de violência doméstica contra a mulher, entendimento depois consolidado na Súmula 542 do STJ."},
{"id": 11735, "materia": "igual", "nivel": 4, "enunciado": "Pela Lei 14.611/2023, as pessoas jurídicas de direito privado com 100 ou mais empregados devem publicar relatórios de transparência salarial e de critérios remuneratórios:", "opcoes": ["Semestralmente, sob pena de multa de até 3% da folha, limitada a 100 salários mínimos", "Anualmente, sob pena de multa fixa de 10 salários mínimos", "A cada dois anos, sem previsão de multa", "Apenas quando houver denúncia de discriminação"], "explicacao": "Art. 5º, caput e § 3º, da Lei 14.611/2023. Os relatórios são publicados em março e setembro, observada a LGPD."},
{"id": 11736, "materia": "igual", "nivel": 4, "enunciado": "A Lei 14.540/2023 instituiu o Programa de Prevenção e Enfrentamento ao Assédio Sexual e demais Crimes contra a Dignidade Sexual e à Violência Sexual, aplicável:", "opcoes": ["À administração pública direta e indireta da União, dos estados, do DF e dos municípios", "Apenas às empresas privadas com mais de 100 empregados", "Somente aos órgãos do Poder Judiciário", "Apenas às universidades públicas federais"], "explicacao": "O programa prevê capacitação de agentes públicos, divulgação de canais de denúncia e boas práticas de prevenção em todos os entes federativos."},
{"id": 11737, "materia": "pcd", "nivel": 0, "enunciado": "O Dia Internacional das Pessoas com Deficiência, instituído pela ONU, é celebrado em:", "opcoes": ["3 de dezembro", "21 de setembro", "8 de março", "5 de junho"], "explicacao": "A ONU celebra o dia em 3 de dezembro. No Brasil, o Dia Nacional de Luta da Pessoa com Deficiência é 21 de setembro."},
{"id": 11738, "materia": "pcd", "nivel": 0, "enunciado": "O intérprete de Libras traduz a comunicação, principalmente, para pessoas:", "opcoes": ["Surdas", "Cegas", "Com mobilidade reduzida", "Idosas"], "explicacao": "A Libras é a língua usada pela comunidade surda. Para pessoas cegas, os recursos mais comuns são o Braille, a audiodescrição e os leitores de tela."},
{"id": 11739, "materia": "pcd", "nivel": 0, "enunciado": "O piso tátil, com relevos no chão das calçadas e estações, serve para:", "opcoes": ["Orientar pessoas cegas ou com baixa visão", "Enfeitar as calçadas", "Evitar que a água empoce", "Indicar onde os carros podem estacionar"], "explicacao": "O piso tátil direcional guia o caminho, e o de alerta avisa sobre obstáculos, escadas e mudanças de nível."},
{"id": 11740, "materia": "pcd", "nivel": 0, "enunciado": "A legenda nos vídeos e na televisão ajuda principalmente pessoas:", "opcoes": ["Surdas ou com deficiência auditiva", "Com deficiência física", "Que não sabem ler", "Com deficiência visual"], "explicacao": "Legendas e janela de Libras tornam o conteúdo audiovisual acessível a quem não ouve ou ouve pouco."},
{"id": 11741, "materia": "pcd", "nivel": 0, "enunciado": "Botões de elevador com escrita em Braille e aviso sonoro de andar são feitos para atender pessoas:", "opcoes": ["Com deficiência visual", "Com deficiência auditiva", "Com nanismo", "Com deficiência intelectual"], "explicacao": "O Braille permite a leitura tátil e o aviso sonoro informa o andar, garantindo autonomia a quem não enxerga."},
{"id": 11742, "materia": "pcd", "nivel": 0, "enunciado": "A sigla TEA significa:", "opcoes": ["Transtorno do Espectro Autista", "Tratamento Especial Adaptado", "Tecnologia de Ensino Assistido", "Termo de Escolaridade Avançada"], "explicacao": "A Lei 12.764/2012 considera a pessoa com TEA pessoa com deficiência, para todos os efeitos legais."},
{"id": 11743, "materia": "pcd", "nivel": 0, "enunciado": "Ao ver uma pessoa com deficiência que parece precisar de ajuda, a atitude mais adequada é:", "opcoes": ["Perguntar se ela quer ajuda e como ajudar", "Pegar a pessoa pelo braço sem falar nada", "Ignorar, para não constranger", "Falar alto e devagar, como se ela não entendesse"], "explicacao": "Respeitar a autonomia significa oferecer ajuda e seguir as orientações da própria pessoa."},
{"id": 11744, "materia": "pcd", "nivel": 0, "enunciado": "O termo considerado correto, hoje, para se referir a quem tem deficiência é:", "opcoes": ["Pessoa com deficiência", "Portador de deficiência", "Deficiente", "Pessoa especial"], "explicacao": "A Convenção da ONU e a Lei Brasileira de Inclusão adotam “pessoa com deficiência”. Deficiência não se “porta”, e a expressão coloca a pessoa em primeiro lugar."},
{"id": 11745, "materia": "pcd", "nivel": 0, "enunciado": "A bengala branca é usada, principalmente, por pessoas:", "opcoes": ["Cegas", "Surdas", "Com deficiência intelectual", "Com autismo"], "explicacao": "A bengala branca ajuda a pessoa cega a identificar obstáculos e sinaliza sua condição para os outros."},
{"id": 11746, "materia": "pcd", "nivel": 0, "enunciado": "A Língua Brasileira de Sinais (Libras) é:", "opcoes": ["Uma língua com gramática própria", "Um conjunto de mímicas sem regras", "Igual em todos os países do mundo", "O português escrito com as mãos, letra por letra"], "explicacao": "A Libras tem estrutura gramatical própria e é diferente das línguas de sinais de outros países. Soletrar letra por letra (datilologia) é apenas um de seus recursos."},
{"id": 11747, "materia": "pcd", "nivel": 1, "enunciado": "A Convenção Internacional sobre os Direitos das Pessoas com Deficiência foi incorporada ao direito brasileiro com status de:", "opcoes": ["Emenda constitucional", "Lei ordinária", "Decreto regulamentar", "Norma supralegal, abaixo da Constituição"], "explicacao": "A Convenção de Nova York e seu Protocolo Facultativo foram aprovados pelo rito do art. 5º, § 3º, da CF e promulgados pelo Decreto 6.949/2009."},
{"id": 11748, "materia": "pcd", "nivel": 1, "enunciado": "O preconceito e a discriminação contra pessoas com deficiência são chamados de:", "opcoes": ["Capacitismo", "Etarismo", "Xenofobia", "Misoginia"], "explicacao": "Capacitismo é tratar a pessoa com deficiência como incapaz ou inferior. Etarismo é preconceito de idade; xenofobia, contra estrangeiros; misoginia, ódio às mulheres."},
{"id": 11749, "materia": "pcd", "nivel": 1, "enunciado": "O Benefício de Prestação Continuada (BPC) garante à pessoa com deficiência de baixa renda:", "opcoes": ["Um salário mínimo mensal", "Meio salário mínimo por mês", "Uma cesta básica mensal", "Isenção de todos os impostos"], "explicacao": "O BPC, previsto na LOAS (Lei 8.742/1993), paga um salário mínimo à pessoa com deficiência e ao idoso a partir de 65 anos sem meios de prover a própria manutenção."},
{"id": 11750, "materia": "pcd", "nivel": 1, "enunciado": "Pela LBI, a pessoa com deficiência tem atendimento prioritário, entre outras situações, na:", "opcoes": ["Restituição de imposto de renda", "Escolha de cargos comissionados", "Isenção de qualquer tributo", "Dispensa de prazos processuais"], "explicacao": "Art. 9º, VII, da Lei 13.146/2015, além da prioridade em processos, atendimento em órgãos públicos, socorro e acesso a informações."},
{"id": 11751, "materia": "pcd", "nivel": 1, "enunciado": "A deficiência múltipla é:", "opcoes": ["A associação de duas ou mais deficiências", "A deficiência que atinge os dois olhos", "Qualquer deficiência de longo prazo", "A deficiência adquirida depois dos 18 anos"], "explicacao": "Deficiência múltipla é a associação de duas ou mais deficiências na mesma pessoa, como a surdocegueira."},
{"id": 11752, "materia": "pcd", "nivel": 1, "enunciado": "Pelo chamado modelo social da deficiência, adotado pela LBI, a deficiência resulta:", "opcoes": ["Da interação entre impedimentos e barreiras da sociedade", "Apenas da condição médica da pessoa, atestada por laudo", "Da falta de esforço da própria pessoa para se adaptar ao meio", "De um diagnóstico médico que impede qualquer tipo de trabalho"], "explicacao": "Pela LBI e pela Convenção da ONU, a deficiência não está só no corpo: barreiras físicas, de comunicação e de atitude é que restringem a participação."},
{"id": 11753, "materia": "pcd", "nivel": 1, "enunciado": "A Lei 14.768/2023 passou a definir deficiência auditiva como limitação de longo prazo da audição:", "opcoes": ["Unilateral total ou bilateral parcial ou total", "Apenas bilateral e total, comprovada por audiometria", "Apenas unilateral parcial, em qualquer grau de perda", "Somente quando a pessoa precisa usar aparelho auditivo"], "explicacao": "A Lei 14.768/2023 incluiu a perda auditiva unilateral total no conceito, além da bilateral parcial ou total."},
{"id": 11754, "materia": "pcd", "nivel": 1, "enunciado": "A Lei 10.048/2000 garante atendimento prioritário a pessoas com deficiência e também, entre outras, a:", "opcoes": ["Obesos, gestantes, lactantes e doadores de sangue", "Todos os servidores públicos em horário de expediente", "Estudantes universitários com carteira estudantil válida", "Pessoas com mais de 50 anos, sem outro requisito"], "explicacao": "A Lei 10.048/2000 prevê prioridade para pessoas com deficiência, pessoas com TEA, idosos a partir de 60 anos, gestantes, lactantes, pessoas com crianças de colo, obesos, pessoas com mobilidade reduzida e doadores de sangue."},
{"id": 11755, "materia": "pcd", "nivel": 1, "enunciado": "A Lei 8.989/1995 concede à pessoa com deficiência, na compra de automóvel, isenção do:", "opcoes": ["IPI", "IPTU", "ITBI", "ISS"], "explicacao": "A Lei 8.989/1995 isenta de IPI a compra de carro por pessoa com deficiência física, visual, auditiva, mental severa ou profunda ou com TEA, observados os requisitos e limites legais."},
{"id": 11756, "materia": "pcd", "nivel": 1, "enunciado": "A Lei Brasileira de Inclusão define como barreiras tecnológicas aquelas que:", "opcoes": ["Dificultam ou impedem o acesso às tecnologias", "Existem apenas em prédios antigos, construídos antes de 2015", "Decorrem da falta de rampas e de corrimãos nas calçadas", "Envolvem o preconceito e as piadas de colegas de trabalho"], "explicacao": "Art. 3º, IV, f, da Lei 13.146/2015. Rampas são barreiras arquitetônicas; o preconceito é barreira atitudinal."},
{"id": 11757, "materia": "pcd", "nivel": 2, "enunciado": "O Tratado de Marraqueche, incorporado com status de emenda constitucional, busca facilitar o acesso a obras publicadas às pessoas:", "opcoes": ["Cegas ou com dificuldade para ler textos impressos", "Surdas, por meio de legendas obrigatórias em filmes e séries", "Com deficiência física, por meio de rampas em bibliotecas públicas", "Com deficiência intelectual, por meio de livros em versão simplificada"], "explicacao": "O Tratado de Marraqueche (Decreto 9.522/2018) permite a produção de cópias em formatos acessíveis, como Braille e áudio, sem autorização do autor."},
{"id": 11758, "materia": "pcd", "nivel": 2, "enunciado": "Pela Lei 8.213/1991, a dispensa de empregado com deficiência contratado para cumprir a cota legal:", "opcoes": ["Só ocorre após contratar substituto em condição semelhante", "É proibida em qualquer hipótese, mesmo por justa causa comprovada", "Pode ocorrer livremente, a qualquer tempo, sem nenhuma condição", "Depende de autorização judicial prévia da Justiça do Trabalho"], "explicacao": "Art. 93, § 1º, da Lei 8.213/1991: a dispensa imotivada só pode ocorrer depois da contratação de substituto em condição semelhante."},
{"id": 11759, "materia": "pcd", "nivel": 2, "enunciado": "Pela LBI, a educação inclusiva deve garantir aos estudantes surdos a oferta de educação bilíngue, com:", "opcoes": ["Libras como primeira língua e português escrito como segunda", "Português falado como única língua de ensino em toda a escola", "Inglês e Libras como línguas obrigatórias desde a educação infantil", "Leitura labial obrigatória em todas as aulas e avaliações"], "explicacao": "Art. 28, IV, da Lei 13.146/2015. A Lei 14.191/2021 incluiu na LDB a educação bilíngue de surdos como modalidade de ensino."},
{"id": 11760, "materia": "pcd", "nivel": 2, "enunciado": "No concurso público, o candidato com deficiência pode pedir, conforme sua necessidade:", "opcoes": ["Adaptação das provas e tempo adicional", "Dispensa de todas as provas", "Nota mínima menor que a dos demais candidatos", "Aprovação automática nas vagas reservadas"], "explicacao": "O Decreto 9.508/2018 garante adaptações razoáveis, tecnologias assistivas e tempo adicional, mas o candidato concorre em igualdade de condições quanto ao conteúdo e à nota mínima."},
{"id": 11761, "materia": "pcd", "nivel": 2, "enunciado": "Pela Lei 7.853/1989, obstar a inscrição em concurso público ou o acesso de alguém a cargo público em razão de sua deficiência é crime punido com:", "opcoes": ["Reclusão de 2 a 5 anos e multa", "Detenção de 1 a 3 meses", "Apenas multa administrativa", "Advertência por escrito"], "explicacao": "Art. 8º, II, da Lei 7.853/1989, com a redação dada pela LBI."},
{"id": 11762, "materia": "pcd", "nivel": 2, "enunciado": "Após a LBI, o Código Civil passou a considerar absolutamente incapazes de exercer pessoalmente os atos da vida civil apenas:", "opcoes": ["Os menores de 16 anos", "As pessoas com deficiência intelectual", "Os menores de 18 anos", "As pessoas interditadas por qualquer motivo"], "explicacao": "Art. 3º do Código Civil, com a redação da Lei 13.146/2015. A deficiência, por si só, não afeta a capacidade civil."},
{"id": 11763, "materia": "pcd", "nivel": 2, "enunciado": "Pela LBI, a acessibilidade nos sítios da internet é obrigatória para:", "opcoes": ["Empresas com sede ou representação no país e órgãos de governo", "Apenas sites de órgãos do Poder Judiciário e do Ministério Público", "Somente sites de bancos e de instituições financeiras autorizadas", "Apenas lojas virtuais com mais de 1 milhão de clientes cadastrados"], "explicacao": "Art. 63 da Lei 13.146/2015: os sites devem seguir as melhores práticas e diretrizes internacionais de acessibilidade."},
{"id": 11764, "materia": "pcd", "nivel": 2, "enunciado": "Pela Lei 12.764/2012, o gestor escolar que recusar a matrícula de aluno com transtorno do espectro autista está sujeito a:", "opcoes": ["Multa de 3 a 20 salários mínimos", "Advertência verbal, sem outras consequências", "Prisão em flagrante", "Perda automática do diploma"], "explicacao": "Art. 7º da Lei 12.764/2012. Em caso de reincidência apurada em processo administrativo, cabe também a perda do cargo."},
{"id": 11765, "materia": "pcd", "nivel": 2, "enunciado": "A tecnologia que permite que um computador leia em voz alta o conteúdo da tela, usada por pessoas cegas, é o:", "opcoes": ["Leitor de tela", "Mouse óptico", "Teclado numérico", "Modo avião"], "explicacao": "Leitores de tela, como NVDA e TalkBack, são exemplos de tecnologia assistiva."},
{"id": 11766, "materia": "pcd", "nivel": 2, "enunciado": "Pela Lei 10.098/2000, os elementos do mobiliário urbano, como telefones e caixas de correio, devem ser:", "opcoes": ["Projetados para uso por pessoas com deficiência ou mobilidade reduzida", "Instalados apenas em ruas de bairros centrais e áreas comerciais", "Retirados das calçadas para evitar acidentes com pedestres", "Pintados de vermelho para serem vistos de longe por todos"], "explicacao": "A Lei 10.098/2000 estabelece normas gerais de acessibilidade para vias públicas, mobiliário urbano e edificações."},
{"id": 11767, "materia": "pcd", "nivel": 3, "enunciado": "Pela Lei 12.764/2012, o aluno com transtorno do espectro autista incluído em classe comum do ensino regular tem direito, em caso de comprovada necessidade, a:", "opcoes": ["Acompanhante especializado", "Ensino exclusivamente domiciliar", "Aprovação automática de série", "Turma separada dos demais alunos"], "explicacao": "Art. 3º, parágrafo único, da Lei 12.764/2012."},
{"id": 11768, "materia": "pcd", "nivel": 3, "enunciado": "O auxílio-inclusão, regulamentado pela Lei 14.176/2021, corresponde a:", "opcoes": ["50% do valor do BPC", "Um salário mínimo integral", "25% do salário de contribuição", "Duas vezes o valor do BPC"], "explicacao": "O auxílio-inclusão é pago à pessoa com deficiência moderada ou grave que recebia o BPC e passa a exercer atividade remunerada, no valor de metade do benefício."},
{"id": 11769, "materia": "pcd", "nivel": 3, "enunciado": "Pela LBI, nos processos seletivos para ingresso no ensino superior, deve ser assegurada à pessoa com deficiência, mediante solicitação prévia:", "opcoes": ["Tempo adicional e recursos de acessibilidade", "Dispensa da prova de redação e da prova discursiva", "Nota extra de 10% em todas as provas objetivas", "Aprovação direta, sem participar do processo seletivo"], "explicacao": "Art. 30 da Lei 13.146/2015: provas em formatos acessíveis, tempo adicional, tradução em Libras e critérios de avaliação que considerem a singularidade linguística da pessoa surda."},
{"id": 11770, "materia": "pcd", "nivel": 3, "enunciado": "Entre os princípios da Convenção da ONU sobre os Direitos das Pessoas com Deficiência está:", "opcoes": ["O respeito pela autonomia individual e pelas próprias escolhas", "A tutela obrigatória de toda pessoa com deficiência pelo Estado, em todos os atos da vida", "A educação em escolas exclusivas e separadas para pessoas com deficiência", "A internação como regra para pessoas com deficiência mental ou intelectual"], "explicacao": "O art. 3º da Convenção inclui dignidade, autonomia, não discriminação, participação plena, respeito à diferença, igualdade de oportunidades e acessibilidade."},
{"id": 11771, "materia": "pcd", "nivel": 3, "enunciado": "Pela LBI, a deficiência não afeta a plena capacidade civil da pessoa, inclusive para:", "opcoes": ["Exercer guarda, tutela, curatela e adoção em igualdade", "Ser dispensada de pagar tributos federais, estaduais e municipais", "Votar em dobro nas eleições, como forma de compensação histórica", "Ser eleita para cargo público sem precisar de filiação partidária"], "explicacao": "Art. 6º da Lei 13.146/2015: a deficiência não afeta a capacidade para casar, ter filhos, decidir sobre planejamento familiar e exercer guarda, tutela, curatela e adoção."},
{"id": 11772, "materia": "pcd", "nivel": 3, "enunciado": "Pela LBI, a pessoa com deficiência submetida a medida restritiva de liberdade:", "opcoes": ["Tem todos os direitos dos demais presos, inclusive acessibilidade", "Perde o direito à assistência jurídica gratuita durante a execução", "Deve cumprir a pena obrigatoriamente em hospital psiquiátrico de custódia", "Fica dispensada de qualquer pena, por força da Lei Brasileira de Inclusão"], "explicacao": "Art. 79, § 2º, da Lei 13.146/2015."},
{"id": 11773, "materia": "pcd", "nivel": 3, "enunciado": "A Lei 12.764/2012 caracteriza o transtorno do espectro autista, entre outros aspectos, por:", "opcoes": ["Déficit persistente na comunicação e interação social, com comportamentos repetitivos", "Perda total da visão ainda na infância, confirmada por exame oftalmológico", "Deficiência física adquirida em acidente de trânsito ou de trabalho", "Perda auditiva bilateral severa, que impede a comunicação oral"], "explicacao": "Art. 1º, § 1º, da Lei 12.764/2012, que define as características clínicas usadas para identificar o TEA."},
{"id": 11774, "materia": "pcd", "nivel": 3, "enunciado": "Pela LBI, o direito ao trabalho da pessoa com deficiência inclui a vedação de:", "opcoes": ["Discriminação em razão da deficiência, inclusive na admissão", "Contratação de pessoas com deficiência por empresas privadas de qualquer porte", "Pagamento de salário igual ao dos demais empregados que exercem a mesma função", "Promoção de pessoas com deficiência a cargos de chefia e direção"], "explicacao": "Art. 34, § 3º, da Lei 13.146/2015, que também garante igualdade de oportunidades e remuneração."},
{"id": 11775, "materia": "pcd", "nivel": 3, "enunciado": "Na Lei Brasileira de Inclusão, a comunicação abrange, entre outras formas:", "opcoes": ["A Libras, o Braille, a comunicação tátil e a linguagem simples", "Apenas a língua portuguesa escrita, por ser a língua oficial do país", "Somente a fala e a escrita, nas formas tradicionais de comunicação", "Apenas os meios digitais, como aplicativos de mensagens e e-mail"], "explicacao": "Art. 3º, V, da Lei 13.146/2015 lista línguas, visualização de textos, Braille, comunicação tátil, caracteres ampliados, dispositivos multimídia, linguagem simples e outros meios."},
{"id": 11776, "materia": "pcd", "nivel": 3, "enunciado": "A curatela de pessoa com deficiência pode ser compartilhada?", "opcoes": ["Sim, o juiz pode nomear mais de um curador", "Não, a lei só admite um curador para cada pessoa curatelada", "Sim, mas apenas entre pai e mãe casados no civil", "Não, porque a curatela foi extinta pela Lei Brasileira de Inclusão"], "explicacao": "Art. 1.775-A do Código Civil, incluído pela LBI."},
{"id": 11777, "materia": "pcd", "nivel": 4, "enunciado": "No julgamento da ADI 5.357, o STF decidiu que as escolas particulares:", "opcoes": ["Devem cumprir a LBI, sem cobrar extra pelas adaptações", "Podem recusar alunos com deficiência por falta de estrutura física ou de pessoal", "Estão dispensadas da LBI, que vale apenas para as escolas públicas", "Podem cobrar taxa extra proporcional ao custo do profissional de apoio"], "explicacao": "O STF julgou constitucionais os arts. 28, § 1º, e 30 da LBI: a escola privada também deve promover a educação inclusiva, sem repassar custos específicos às famílias."},
{"id": 11778, "materia": "pcd", "nivel": 4, "enunciado": "Pela Lei 8.213/1991, uma empresa com 600 empregados deve preencher com pessoas com deficiência ou reabilitadas, no mínimo:", "opcoes": ["4% dos cargos, ou seja, 24 vagas", "2% dos cargos, ou seja, 12 vagas", "5% dos cargos, ou seja, 30 vagas", "3% dos cargos, ou seja, 18 vagas"], "explicacao": "Art. 93: até 200 empregados, 2%; de 201 a 500, 3%; de 501 a 1.000, 4%; acima de 1.000, 5%. 4% de 600 = 24."},
{"id": 11779, "materia": "pcd", "nivel": 4, "enunciado": "No RE 567.985, o STF decidiu, quanto ao critério de renda familiar per capita inferior a 1/4 do salário mínimo para o BPC, que:", "opcoes": ["Não pode ser o único meio de provar a miserabilidade", "É absoluto e não admite qualquer prova em contrário apresentada pelo requerente", "Deixou de existir, e o BPC passou a ser pago a qualquer pessoa, sem critério de renda", "Foi substituído pela comprovação de patrimônio mínimo em nome da família"], "explicacao": "O STF declarou a inconstitucionalidade parcial, sem pronúncia de nulidade, do critério como única forma de aferição. A legislação posterior passou a admitir outros elementos de vulnerabilidade."},
{"id": 11780, "materia": "pcd", "nivel": 4, "enunciado": "Pela LBI, a pena do crime de apropriar-se de bens, pensão ou rendimentos de pessoa com deficiência aumenta de 1/3 se o crime é cometido por:", "opcoes": ["Tutor, curador, inventariante ou depositário judicial, entre outros", "Qualquer pessoa que more na mesma cidade da vítima, ainda que sem vínculo", "Pessoa com menos de 21 anos, à época do fato, sem antecedentes", "Empregado de instituição financeira, somente, no exercício da função"], "explicacao": "Art. 89, parágrafo único, da Lei 13.146/2015, que também alcança quem se apropriou em razão de ofício ou profissão."},
{"id": 11781, "materia": "pcd", "nivel": 4, "enunciado": "O art. 12 da Convenção da ONU sobre os Direitos das Pessoas com Deficiência garante:", "opcoes": ["O reconhecimento igual perante a lei, com capacidade legal", "A substituição da vontade da pessoa por um tutor em todos os atos da vida civil", "A internação compulsória como medida de proteção da própria pessoa", "A dispensa de responsabilidade civil e penal em qualquer situação"], "explicacao": "O art. 12 inspirou a LBI a substituir o modelo de interdição ampla pela regra da capacidade e por apoios, como a tomada de decisão apoiada."},
{"id": 11782, "materia": "pcd", "nivel": 4, "enunciado": "Pela LBI, as emissoras de televisão devem permitir o uso de recursos de acessibilidade como:", "opcoes": ["Legenda oculta, janela de Libras e audiodescrição", "Apenas legenda em inglês nos filmes estrangeiros", "Somente som estéreo de alta qualidade em todos os canais", "Apenas aumento automático do volume nos intervalos"], "explicacao": "Art. 67 da Lei 13.146/2015, sobre os serviços de radiodifusão de sons e imagens."},
{"id": 11783, "materia": "pcd", "nivel": 4, "enunciado": "Pela LBI, a aprovação de projeto arquitetônico e a concessão de alvará de funcionamento de edificações abertas ao público estão condicionadas:", "opcoes": ["À observância das regras de acessibilidade", "Ao pagamento de taxa especial de inclusão", "À contratação de intérprete de Libras em tempo integral", "À autorização do Conselho Nacional dos Direitos da Pessoa com Deficiência"], "explicacao": "Art. 60, § 1º, da Lei 13.146/2015: o alvará e a carta de habite-se dependem do cumprimento das normas de acessibilidade."},
{"id": 11784, "materia": "pcd", "nivel": 4, "enunciado": "Pela Lei 13.977/2020 (Lei Romeo Mion), a Carteira de Identificação da Pessoa com Transtorno do Espectro Autista (Ciptea):", "opcoes": ["É gratuita e tem validade de 5 anos", "É paga e vale por toda a vida, sem necessidade de renovação", "Substitui a carteira de identidade para todos os fins legais", "Só pode ser emitida pelo Poder Judiciário, por decisão de um juiz"], "explicacao": "A Ciptea é emitida pelos órgãos responsáveis pela política do TEA nos estados, no DF e nos municípios, sem custo, com validade de 5 anos e dados atualizados na renovação."},
{"id": 11785, "materia": "pcd", "nivel": 4, "enunciado": "Pela LBI, o Cadastro Nacional de Inclusão da Pessoa com Deficiência (Cadastro-Inclusão) tem a finalidade de:", "opcoes": ["Reunir dados para caracterizar a pessoa com deficiência e as barreiras que enfrenta", "Substituir a avaliação biopsicossocial da deficiência feita pela equipe multiprofissional", "Registrar apenas os servidores públicos com deficiência para fins de promoção", "Conceder automaticamente o BPC a quem se cadastrar, sem outra análise"], "explicacao": "Art. 92 da Lei 13.146/2015: o Cadastro-Inclusão é registro público eletrônico para formular, gerir e avaliar políticas públicas."},
{"id": 11786, "materia": "pcd", "nivel": 4, "enunciado": "Pela LBI (art. 2º-A, incluído pela Lei 14.624/2023), o uso do cordão de fita com desenhos de girassóis por pessoas com deficiências ocultas:", "opcoes": ["É opcional e não dispensa documento comprobatório, se solicitado", "É obrigatório para ter acesso ao atendimento prioritário", "Substitui qualquer laudo ou documento sobre a deficiência", "Só é permitido a pessoas com transtorno do espectro autista"], "explicacao": "§ 1º: o uso é opcional e sua ausência não prejudica direitos. § 2º: o símbolo não dispensa a apresentação de documento comprobatório da deficiência, se solicitado pelo atendente ou autoridade."}
]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));

-- Conferência: deve mostrar 10 questões em cada nível de igual e pcd, e 5 de ia revisadas.
select materia, nivel, count(*) as qtd
from public.questoes
where id between 11687 and 11786 or id in (3166, 3167, 3168, 3274, 3275)
group by materia, nivel
order by materia, nivel;

select public.questoes_versao() as nova_versao;
